pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address to, uint256 v) public {
        vm.assume(caddress != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok = true;
        try c.transfer(from, caddress, tos, v) returns (bool r) { ok = r; } catch { ok = true; }
        // Rule: any call to transfer that completes must report success (true).
        assertTrue(ok);
    }
}
contract SucceedingToken { fallback() external { assembly { mstore(0x00, 0x01) return(0x00, 0x20) } } }
